            <p v-if="!visibleOrganizations.length" class="empty-state">No companies match your search.</p>
          </section>
          <aside v-if="selectedOrganization" class="panel company-drawer" :style="billingBrand(selectedOrganization)" aria-label="Company billing details"><div class="panel-heading"><div><span class="eyebrow">COMPANY DETAILS</span><h2>{{ selectedOrganization.name }}</h2></div><button class="icon-button" aria-label="Close company details" @click="selectedCompanyId = null">×</button></div><p class="subtle">{{ selectedOrganization.connection?.configured ? 'Clearinghouse credentials configured' : 'Clearinghouse setup needed' }} · {{ selectedOrganization.connection?.mode || 'disabled' }}</p><div class="drawer-stats"><div><strong>{{ selectedOrganization.counts?.ready ?? (selectedOrganization.counts ? 0 : '—') }}</strong><span>Ready for review</span></div><div><strong>{{ attentionCount(selectedOrganization) }}</strong><span>Need attention</span></div></div><h3>Next actions</h3><button class="action-row" @click="openCompanyQueue(selectedOrganization, 'attention')">Review rejections and denials <span>→</span></button><button class="action-row" @click="openCompanyQueue(selectedOrganization, 'ready')">Review prepared claims <span>→</span></button><button class="action-row" @click="drillInto(selectedOrganization, 'payers')">Check payer and ERA enrollment <span>→</span></button><button class="action-row" @click="drillInto(selectedOrganization, 'reports')">Open company reports <span>→</span></button><p class="subtle">Payment totals will appear after ERA reconciliation is available.</p><button class="primary wide" @click="drillInto(selectedOrganization, 'claims')">Work in {{ selectedOrganization.name }}</button></aside>
