          <p v-if="capabilities.claims && !claims.length && !loading" class="empty-state">No claims match this scope and filter.</p><div class="pagination"><span>{{ total.toLocaleString() }} claims · Page {{ page }} of {{ Math.max(1, Math.ceil(total / 30)) }}</span><div><button class="secondary" :disabled="loading || page <= 1" @click="page--">Previous</button><button class="secondary" :disabled="loading || page * 30 >= total" @click="page++">Next</button></div></div>
