        </section>
        <ClaimMdWorkspace v-if="section === 'claims' && scopedOrganization" :key="`drafts-${scopeId}`" :agency-id="scopedOrganization.id" :connection="scopedOrganization.connection || {}" section="claims" @updated="reload" />

