        <PayerEftPanel v-if="['payers', 'payments'].includes(section) && scopedOrganization" :key="`eft-${scopeId}`" :agency-id="scopedOrganization.id" @updated="reload" />
        <ClaimMdWorkspace v-if="section === 'payers' && scopedOrganization" :key="`payers-${scopeId}`" :agency-id="scopedOrganization.id" :connection="scopedOrganization.connection || {}" section="payers" @updated="reload" />

        <template v-if="section === 'payments'">
          <section class="panel"><div class="panel-heading"><div><h2>Remittance reconciliation</h2><p>Follow each ERA from receipt through matching, review, and posting.</p></div><a href="https://www.claim.md/" target="_blank" rel="noopener noreferrer" class="secondary">Open Claim.MD ↗</a></div><div class="reconciliation-steps"><div v-for="(step, index) in ['ERA received', 'Match to claim', 'Review adjustments', 'Post payment']" :key="step"><b>{{ index + 1 }}</b><h3>{{ step }}</h3><span class="badge neutral">{{ index === 0 ? 'Directory lookup available' : 'Not yet available' }}</span></div></div><div class="empty-state"><h3>Payment posting is not enabled yet</h3><p>ERA matching, adjustments, reversals, denials, and patient responsibility need reconciliation before they can be posted. No payment totals are inferred from accepted claims.</p></div><div class="panel-toolbar"><label>Company <select v-model="scopeId"><option value="all">Select a company</option><option v-for="org in organizations" :key="org.id" :value="String(org.id)">{{ org.name }}</option></select></label><button class="primary" :disabled="!scopedOrganization?.connection?.configured || eraLoading" @click="loadEras">{{ eraLoading ? 'Checking…' : 'Check ERA directory' }}</button></div><p v-if="eraError" class="error-banner" role="alert">{{ eraError }}</p><p v-if="eraChecked && !eraRows.length" class="empty-state">No remittances returned for this company’s Tax ID.</p><div v-if="eraRows.length" class="table-scroll"><table><thead><tr><th>ERA ID</th><th>Payer</th><th>Received / payment date</th><th>Reconciliation</th></tr></thead><tbody><tr v-for="(era, index) in eraRows" :key="era.eraid || index"><td>{{ era.eraid || '—' }}</td><td>{{ era.payer_name || era.payerid || '—' }}</td><td>{{ date(era.received_date || era.check_date) }}</td><td><span class="badge warning">Review in Claim.MD</span></td></tr></tbody></table></div><p class="panel-note">ERA directory results are not posted payments. Shared Tax IDs may require claim-level matching before remittances can be shown safely.</p></section>
        </template>

        <template v-if="section === 'reports'">
          <section class="panel"><div class="panel-heading"><div><h2>Claims by stage</h2><p>Current workload for {{ scopedOrganization?.name || 'all authorized companies' }}.</p></div></div><div v-if="totals" class="status-chart"><button v-for="bar in reportBars" :key="bar.status" @click="filterQueue(bar.status)"><span>{{ bar.label }}</span><span class="bar-track"><i :style="{ width: `${bar.value ? Math.max(2, bar.value / maxBar * 100) : 0}%` }"></i></span><strong>{{ bar.value }}</strong></button></div><p class="panel-note">Collections, payment speed and patient-responsibility reporting will become available after verified payment reconciliation.</p></section>
          <MedicalBillingReportsPanel v-if="scopedOrganization" :key="`reports-${scopeId}`" :agency-id="scopedOrganization.id" />
          <section v-else class="panel empty-state"><h2>Detailed company reports</h2><p>Select a company to run and export claims, service-line, clinical, and billing reports.</p></section>
          <section class="panel"><h2>Saved views</h2><p class="subtle">Save this scope and claim filter in this browser. Saved views contain no claim or patient data.</p><form class="panel-toolbar" @submit.prevent="saveView"><input v-model="savedViewName" maxlength="60" placeholder="View name" aria-label="Saved view name" required /><button class="secondary">Save current view</button></form><div v-for="view in savedViews" :key="view.id" class="saved-view"><button class="text-button" @click="restoreView(view)">{{ view.name }}</button><button class="icon-button" :aria-label="`Remove ${view.name}`" @click="removeView(view.id)">×</button></div><p class="panel-note">Scheduled report delivery is not enabled. Company reports can be exported on demand.</p></section>
        </template>

        <template v-if="section === 'settings'"><BillingCostPlanner /><section class="panel"><h2>Company billing settings</h2><p>Choose a company to manage service codes, billing locations, fees, and clearinghouse configuration.</p><select v-model="scopeId"><option value="all">Select a company</option><option v-for="org in organizations" :key="org.id" :value="String(org.id)">{{ org.name }}</option></select></section><SupervisedPayerPolicies v-if="scopedOrganization" :key="`policies-${scopeId}`" :agency-id="scopedOrganization.id" /><MedicalBillingView v-if="scopedOrganization" :key="`settings-${scopeId}`" :billing-agency-id="scopedOrganization.id" :billing-agency-slug="scopedOrganization.slug" /></template>
      </template>
    </main>

    <div v-if="selectedClaim" class="claim-overlay" @click.self="closeClaim"><aside class="claim-drawer" role="dialog" aria-modal="true" aria-labelledby="claim-dialog-title" tabindex="-1" ref="claimDialog" @keydown="trapClaimFocus"><div class="panel-heading"><div><span class="eyebrow">{{ companyName(selectedClaim.agency_id) }}</span><h2 id="claim-dialog-title">{{ selectedClaim.claim_number || `Claim #${selectedClaim.id}` }}</h2></div><button class="icon-button" aria-label="Close claim" @click="closeClaim">×</button></div><p>Note #{{ selectedClaim.clinical_note_id || 'missing' }} · Session #{{ selectedClaim.clinical_session_id }} · Client #{{ selectedClaim.client_id }}</p><span class="badge" :class="claimStatusTone(selectedClaim.claim_lifecycle)">{{ claimStatusLabel(selectedClaim.claim_lifecycle) }}</span><div class="panel-toolbar"><button class="secondary" @click="claimTools?.showHistory(selectedClaim.id)">Response history</button><button v-if="editableClaim" class="secondary" @click="claimTools?.editClaim(selectedClaim.id)">Edit billing fields</button><button v-if="editableClaim" class="primary" @click="claimTools?.reviewClaim(selectedClaim.id)">Review for submission</button></div><p v-if="selectedClaim.claim_lifecycle === 'queued'" class="panel-note">Submission is unresolved. Sync and reconcile before attempting another upload.</p><p v-if="selectedClaim.claim_lifecycle === 'denied'" class="panel-note">Review the payer’s adjudication before choosing a corrected claim or appeal. Automatic resubmission is unavailable.</p><SecondaryClaimPanel :agency-id="selectedClaim.agency_id" :claim-id="selectedClaim.id" @created="claimUpdated" /><ClaimMdWorkspace ref="claimTools" :key="`${selectedClaim.agency_id}-${selectedClaim.id}`" :agency-id="Number(selectedClaim.agency_id)" :connection="claimOrganization?.connection || {}" section="detail" @updated="claimUpdated" /></aside></div>
  </div>
</template>

<script setup>
import PayerEftPanel from '../../components/billing/PayerEftPanel.vue';
import BillingCostPlanner from '../../components/billing/BillingCostPlanner.vue';
import SecondaryClaimPanel from '../../components/admin/SecondaryClaimPanel.vue';
import { computed, ref, watch, nextTick, onBeforeUnmount } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { useAgencyStore } from '../../store/agency';
import { useAuthStore } from '../../store/auth';
import api from '../../services/api';
import { toUploadsUrl } from '../../utils/uploadsUrl';
import { billingTotals, billingBrand, claimStatusLabel, claimStatusTone } from '../../utils/billingWorkspace';
import ClaimMdWorkspace from '../../components/admin/ClaimMdWorkspace.vue';
import MedicalBillingReportsPanel from '../../components/admin/MedicalBillingReportsPanel.vue';
import MedicalBillingView from './MedicalBillingView.vue';
import SupervisedPayerPolicies from '../../components/admin/SupervisedPayerPolicies.vue';

const agencyStore = useAgencyStore(), authStore = useAuthStore(), route = useRoute(), router = useRouter();
const navigation = [
  { id: 'workspace', label: 'Billing Workspace', icon: 'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z' },
  { id: 'claims', label: 'Claims', icon: 'M6 3h9l4 4v14H6z M14 3v5h5 M9 12h7 M9 16h7' },
  { id: 'payers', label: 'Payers & ERA', icon: 'M9 8H7a4 4 0 000 8h3 M15 8h2a4 4 0 010 8h-3 M8 12h8' },
  { id: 'payments', label: 'Payments', icon: 'M3 5h18v15H3z M3 10h18 M7 15h4' },
  { id: 'reports', label: 'Reports', icon: 'M4 3v18h17 M8 17v-6 M13 17V7 M18 17V4' },
  { id: 'settings', label: 'Settings', icon: 'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6' }
];
const descriptions = { workspace: 'Manage payer connections, claims, and follow-ups across your organizations.', claims: 'Work the queue, approve claims, and follow clearinghouse and payer responses.', payers: 'Track claims, ERA, eligibility, and EFT direct deposits for every billing company.', payments: 'Review remittances and prepare for verified payment reconciliation.', reports: 'Explore claim performance and export company billing reports.', settings: 'Manage the billing setup for each organization.' };
const section = ref(navigation.some(n => n.id === route.query.billingSection) ? route.query.billingSection : 'workspace');
const scopeId = ref(String(route.query.billingScope || route.query.agencyId || (route.query.claimId ? agencyStore.currentAgency?.id : '') || 'all')), status = ref('all'), page = ref(1), searchInput = ref(String(route.query.claimId || '')), search = ref(String(route.query.claimId || '')), companySearch = ref('');
const organizations = ref([]), claims = ref([]), total = ref(0), capabilities = ref({}), updatedAt = ref(null), loading = ref(false), error = ref('');
const queueMode = ref('claims');
const selectedCompanyId = ref(null), selectedClaim = ref(null), claimTools = ref(null), claimDialog = ref(null);
const eraLoading = ref(false), eraRows = ref([]), eraError = ref(''), eraChecked = ref(false);
let loadSequence = 0, eraSequence = 0, active = true, priorFocus = null, initialClaimId = Number(route.query.claimId || 0);
onBeforeUnmount(() => { active = false; loadSequence++; eraSequence++; });
const scopedOrganization = computed(() => organizations.value.find(o => o.id === Number(scopeId.value)));
const selectedOrganization = computed(() => organizations.value.find(o => o.id === selectedCompanyId.value));
const claimOrganization = computed(() => organizations.value.find(o => o.id === Number(selectedClaim.value?.agency_id)));
const scopedOrganizations = computed(() => scopedOrganization.value ? [scopedOrganization.value] : organizations.value);
const visibleOrganizations = computed(() => scopedOrganizations.value.filter(o => o.name.toLowerCase().includes(companySearch.value.toLowerCase())));
const totals = computed(() => billingTotals(scopedOrganizations.value));
const signedInName = computed(() => [authStore.user?.first_name, authStore.user?.last_name].filter(Boolean).join(' ') || 'Billing staff');
const brandName = computed(() => scopedOrganization.value?.name || agencyStore.currentAgency?.name || 'Billing operations');
const brandLogo = computed(() => logoUrl(scopedOrganization.value?.logoUrl || (scopeId.value === 'all' ? agencyStore.currentAgency?.logo_url : null)));
const pageTitle = computed(() => navigation.find(n => n.id === section.value)?.label);
const editableClaim = computed(() => ['draft', 'ready', 'rejected'].includes(selectedClaim.value?.claim_lifecycle));
const queueTabs = [{ id: 'all', label: 'All claims' }, { id: 'attention', label: 'Needs attention' }, { id: 'draft', label: 'Drafts' }, { id: 'ready', label: 'Ready for review' }, { id: 'in_progress', label: 'In progress' }, { id: 'rejected', label: 'Rejected' }, { id: 'denied', label: 'Denied' }, { id: 'paid', label: 'Marked paid' }];
const payerRows = computed(() => scopedOrganizations.value.flatMap(organization => {
  const grouped = new Map();
  for (const e of organization.enrollments || []) {
    const key = `${organization.id}:${e.officeId}:${e.providerNpi}:${e.payerId}`;
    const row = grouped.get(key) || { key, organization, officeId: e.officeId, providerNpi: e.providerNpi, payerId: e.payerId, claims: 'Not recorded', era: 'Not recorded', eligibility: 'Not recorded' };
    const field = { '1500': 'claims', era: 'era', elig: 'eligibility' }[e.type];
    if (field) row[field] = enrollmentLabel(e.status); grouped.set(key, row);
  }
  for(const e of organization.eft || []) {
    const matches=[...grouped.values()].filter(r=>r.payerId===e.payerId&&r.providerNpi===e.providerNpi);
    if(matches.length)for(const row of matches)row.eft=eftLabel(e);
    else {const key=`eft:${organization.id}:${e.id}`;grouped.set(key,{key,organization,officeId:e.officeId,providerNpi:e.providerNpi,payerId:e.payerId,claims:'Not recorded',era:'Not recorded',eligibility:'Not recorded',eft:eftLabel(e)});}
  }
  return [...grouped.values()];
}));
const connectionQueue = computed(() => scopedOrganizations.value.flatMap(organization => {
  const rows = (organization.enrollments || []).map((e, i) => ({ key: `${organization.id}:${i}`, organization, label: ({ '1500': 'Claims enrollment', era: 'ERA enrollment', elig: 'Eligibility enrollment' })[e.type] || 'Enrollment', payer: `${e.payerId} · Office #${e.officeId}`, status: enrollmentLabel(e.status), at: e.lastEventAt, section: 'payers' }));
  rows.push(...(organization.eft||[]).filter(e=>!e.identityCurrent||e.status!=='active_verified').map(e=>({key:`eft:${organization.id}:${e.id}`,organization,label:'EFT / direct deposit',payer:`${e.payerId} · NPI ${e.providerNpi}`,status:eftLabel(e),at:e.updatedAt,section:'payers'})));
