}));
const reportBars = computed(() => [{ status: 'draft', label: 'Drafts', value: totals.value?.drafts || 0 }, { status: 'ready', label: 'Ready for review', value: totals.value?.ready || 0 }, { status: 'in_progress', label: 'In progress', value: totals.value?.progress || 0 }, { status: 'attention', label: 'Needs attention', value: totals.value?.attention || 0 }, { status: 'paid', label: 'Marked paid', value: totals.value?.paid || 0 }]);
const maxBar = computed(() => Math.max(1, ...reportBars.value.map(b => b.value)));
